import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        n = int(next(iterator))
    except StopIteration:
        return

    sum_diff = 0.0
    for _ in range(n):
        x = int(next(iterator))
        y = int(next(iterator))
        sum_diff += (y - x)

    a = sum_diff / n
    print(f"{a:.6f}")

if __name__ == "__main__":
    solve()

